/*
 * sound_classify.c - see sound_classify.h. The model data comes from sound_model.h (generated).
 */
#include "sound_classify.h"

/* DEVIATION (BARR-C 4.2.c.ii, storage allocated in a header file): sound_model.h is GENERATED by
 * ml/export_c.py and defines the model's static const tables. This file is its only includer, so
 * there is exactly one copy. A hand edit would be overwritten on the next export; the fix belongs
 * in the generator (emit a .c file).
 * Approved by: ____________________ (project manager), date: __________ */
#include "sound_model.h"

/* a variable, not the macro, so a threshold of 101 ("never") does not trip -Wtype-limits */
static const uint32_t k_min_conf = SOUND_STAGE2_MIN_CONF;

void sm_predict(const sm_model_t* p_model, const float* p_features, uint8_t* p_label, uint8_t* p_conf)
{
    uint16_t votes[SM_MAX_CLASSES] = { 0 };
    for (uint32_t tree = 0; tree < p_model->n_trees; tree++)
    {
        const sm_tree_t* p_twid_real = &p_model->p_trees[tree];
        int32_t node = p_twid_real->root;
        while (node >= 0)
        {
            node = p_features[p_twid_real->p_feat[node]] <= p_twid_real->p_thr[node] ? p_twid_real->p_left[node] : p_twid_real->p_right[node];
        }
        const uint8_t* p_dist = p_twid_real->p_leaf + (uint32_t)(-node - 1) * p_model->n_classes;
        for (uint32_t cls = 0; cls < p_model->n_classes; cls++)
        {
            votes[cls] = (uint16_t)(votes[cls] + p_dist[cls]);
        }
    }
    uint32_t best = 0;
    for (uint32_t cls = 1; cls < p_model->n_classes; cls++)
    {
        if (votes[cls] > votes[best]) /* ties keep the lower class, like numpy argmax */
        {
            best = cls;
        }
    }
    *p_label = p_model->p_classes[best];
    *p_conf = (uint8_t)((votes[best] + p_model->n_trees / 2u) / p_model->n_trees);
}

void sound_classify(const float features[SF_N_FEATURES], uint8_t* p_label_id, uint8_t* p_conf)
{
    uint8_t group, conf_a;
    sm_predict(&sm_stage1, features, &group, &conf_a);
    *p_label_id = group;
    *p_conf = conf_a;
    const sm_model_t* p_size_b = sm_stage2_for_group(group);
    if (p_size_b)
    {
        uint8_t animal, conf_b;
        sm_predict(p_size_b, features, &animal, &conf_b);
        const uint8_t conf = (uint8_t)(((uint32_t)conf_a * conf_b + 50u) / 100u);
        if (conf >= k_min_conf)
        {
            *p_label_id = animal;
            *p_conf = conf;
        }
    }
}

uint8_t sound_classify_min_conf(void)
{
    return (uint8_t)k_min_conf;
}
